class BackupEngine:
    def snapshot(self, project_dir: str) -> dict:
        src = Path(project_dir)
        if not src.exists():
            return {"success": False, "error": "Kaynak yok"}
        stamp = time.strftime("%Y%m%d-%H%M%S")
        dest = Path(config.BACKUPS_DIR) / f"{src.name}-{stamp}"
        fs = FileSystemTool()
        dest.parent.mkdir(parents=True, exist_ok=True)
        try:
            shutil.copytree(src, dest, dirs_exist_ok=True, ignore=shutil.ignore_patterns(".venv", "__pycache__"))
            return {"success": True, "path": str(dest)}
        except Exception as e:
            return {"success": False, "error": str(e)}

from __future__ import annotations

import hashlib
import json
import threading
import time
from typing import Any


class TTLCache:
    def __init__(self, ttl_seconds: float = 120.0, max_items: int = 256):
        self.ttl = ttl_seconds
        self.max_items = max_items
        self._data: dict[str, tuple[float, Any]] = {}
        self._lock = threading.Lock()

    @staticmethod
    def make_key(*parts: Any) -> str:
        raw = json.dumps(parts, ensure_ascii=False, sort_keys=True, default=str)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def get(self, key: str) -> Any | None:
        with self._lock:
            item = self._data.get(key)
            if not item:
                return None
            expires, value = item
            if expires < time.time():
                self._data.pop(key, None)
                return None
            return value

    def set(self, key: str, value: Any) -> None:
        with self._lock:
            if len(self._data) >= self.max_items:
                oldest = min(self._data.items(), key=lambda kv: kv[1][0])[0]
                self._data.pop(oldest, None)
            self._data[key] = (time.time() + self.ttl, value)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()


tool_cache = TTLCache(ttl_seconds=90, max_items=128)
response_cache = TTLCache(ttl_seconds=45, max_items=64)

import json
from pathlib import Path
from typing import Optional
import config


class Coder:
    def __init__(self, llm_client, fs_tool, python_tool):
        self.llm = llm_client
        self.fs = fs_tool
        self.python = python_tool

    def code_from_plan(self, step: dict, project_dir: str, context: str = "") -> list[dict]:
        proje_adi = step.get("adim", "")
        dosyalar = step.get("dosyalar", [])
        detay = step.get("detay", "")

        results = []
        for fname in dosyalar:
            full_path = str(Path(project_dir) / fname)
            content = self._generate_file(fname, detay, context, project_dir)
            if content:
                r = self.fs.write_file(full_path, content)
                results.append({"file": fname, "result": r})
            else:
                results.append({"file": fname, "result": {"success": False, "error": "Icerik uretilmedi"}})
        return results

    def _generate_file(self, filename: str, step_detail: str, context: str, project_dir: str) -> Optional[str]:
        prompt = f"""Bir yazilim gelistirme ajani olarak dosya kodu uret.

Proje klasoru: {project_dir}
Uretilecek dosya: {filename}
Adim detayi: {step_detail}

Ek baglam (onceki adimlardan bilgiler):
{context or "Yok"}

KURAL:
- Gecerli, calisir, temiz kod yaz
- Hata yonetimi (try/except) ekle
- logging veya print ile debug ciktilari ekle
- config, .env, sabitler icin ayrismis alanlar kullan
- Script ise if __name__ == "__main__": blogu ekle
- Fonksiyon, sinif ve degisken isimleri acik ve anlamli olsun
- Sadece dosya icerigini yaz, aciklama, markdown, ``` gibi dis seyler YOK.

Sadece kod icerigini dondur:"""
        result = self.llm.generate(prompt, temperature=0.2, label=f"'{filename}' dosyası kodlanıyor")
        result = self._clean_code_block(result)
        return result

    @staticmethod
    def _clean_code_block(text: str) -> str:
        if text is None:
            return ""
        t = text.strip()
        if t.startswith("```"):
            t = t[3:]
            first_line_end = t.find("\n")
            if first_line_end >= 0 and t[:first_line_end].strip().isalpha():
                t = t[first_line_end + 1:]
            else:
                t = t.lstrip("\n")
        if t.endswith("```"):
            t = t[:-3]
        return t.strip("\n") + "\n"

    def fix_code(self, file_path: str, original_code: str, error_info: dict, step_context: str) -> tuple[bool, str]:
        prompt = f"""Asagidaki Python dosyasinda bir hata var. Hatayi analiz edip DUZELTILMIS kodunu dondur.

Dosya: {file_path}
Hata turu: {error_info.get('error_type', 'Bilinmiyor')}
Hata mesaji: {error_info.get('error_message', 'Bilinmiyor')}
Hata satiri: {error_info.get('line', 'Bilinmiyor')}
Hata dosyasi: {error_info.get('file', 'Bilinmiyor')}

Kod:
```
{original_code}
```

Ek baglam:
{step_context}

KURAL:
- Tüm dosyayi, tam calisir halde dondur
- Sadece kodu yaz, aciklama ekleme
- Kodu ``` python blogu icine alma, sadece saf kodu dondur

DUZELTILMIS KOD:"""
        result = self.llm.generate(prompt, temperature=0.1, label="Hata analiz edilip düzeltiliyor")
        cleaned = self._clean_code_block(result)
        return (len(cleaned) > 10, cleaned)

from pathlib import Path
import config
from core.coder import Coder
from core.tester import Tester
from tools.filesystem import FileSystemTool
from tools.python_tool import PythonTool
from core.memory import Memory


class Debugger:
    def __init__(self, llm_client):
        self.coder = Coder(llm_client, FileSystemTool(), PythonTool())
        self.tester = Tester()
        self.fs = FileSystemTool()
        self.python = PythonTool()
        self.max_attempts = config.MAX_DEBUG_ATTEMPTS

    def auto_fix(self, session_id: str, memory: Memory, project_dir: str, test_result: dict, step_context: str = "", max_attempts: int = None) -> dict:
        errors = self.tester.extract_errors(test_result)
        if not errors:
            stderr = test_result.get("stderr", "")
            stdout = test_result.get("stdout", "")
            if stderr.strip():
                errors.append(stderr.strip())
            elif stdout.strip():
                errors.append(stdout.strip()[:2000])
            else:
                return {"fixed": False, "reason": "Belirgin hata ciktilari yakalanamadi"}

        attempt = 0
        limit = max_attempts if max_attempts is not None else self.max_attempts
        last_result = dict(test_result)

        while attempt < limit and errors:
            attempt += 1
            err_block = errors[0]
            err_info = self.python.analyze_python_error(err_block)

            target_file = err_info.get("file")
            if not target_file or not Path(target_file).is_absolute():
                candidates = list(Path(project_dir).rglob("*.py"))
                if candidates:
                    target_file = str(candidates[0])
                else:
                    return {"fixed": False, "reason": "Duzeltilecek hedef dosya bulunamadi", "attempts": attempt}

            try:
                read_r = self.fs.read_file(target_file)
            except Exception:
                read_r = {"success": False, "error": "dosya okunamadi"}
            if not read_r.get("success"):
                return {"fixed": False, "reason": f"Dosya okunamadi: {read_r.get('error')}", "attempts": attempt}

            original_code = read_r["content"]
            heuristic = self._heuristic_fix(original_code, err_info, err_block)
            if heuristic:
                fixed, new_code = True, heuristic
            else:
                fixed, new_code = self.coder.fix_code(target_file, original_code, err_info, step_context)
            if not fixed:
                attempt_info = f"Deneme {attempt}: LLM duzeltilmis kod donmedi"
                memory.add_error(session_id, f"debug_attempt_{attempt}", attempt_info)
                continue

            write_r = self.fs.write_file(target_file, new_code)
            if not write_r.get("success"):
                memory.add_error(session_id, f"debug_write_{attempt}", write_r.get("error", ""))
                continue

            memory.add_fix(
                session_id,
                error_summary=f"{err_info.get('error_type') or 'Hata'}: {(err_info.get('error_message') or '')[:80]}",
                fix_action=f"Dosya duzenlendi: {Path(target_file).name}",
                success=True,
            )

            new_test = self.tester.detect_and_run(project_dir)
            last_result = new_test

            if new_test.get("success"):
                memory.add_step(session_id, "debug", f"Deneme {attempt}: HATA DÜZELTILDI - {err_info.get('error_type', 'Hata')}", new_test)
                return {"fixed": True, "attempts": attempt, "last_result": new_test}

            errors = self.tester.extract_errors(new_test)
            if not errors:
                stderr = new_test.get("stderr", "")
                if stderr.strip():
                    errors.append(stderr)
            memory.add_step(session_id, "debug", f"Deneme {attempt}: Tekrar denenecek - hala hata var", new_test)

        return {"fixed": last_result.get("success", False), "attempts": attempt, "last_result": last_result}

    @staticmethod
    def _heuristic_fix(original_code: str, err_info: dict, err_block: str) -> str | None:
        blob = f"{err_info.get('error_type','')} {err_info.get('error_message','')} {err_block}"
        if "ZeroDivisionError" in blob and " / " in original_code:
            if "if b ==" in original_code or "if b==" in original_code:
                return None
            return original_code.replace(
                "return a / b",
                'if b == 0:\n        return "HATA: Sifira bolunemez"\n    return a / b',
            )
        if "NameError" in blob:
            msg = err_info.get("error_message") or ""
            name = None
            if "name '" in msg:
                name = msg.split("name '", 1)[1].split("'", 1)[0]
            if name and f"{name} =" not in original_code:
                return f"{name} = None\n{original_code}"
        return None

from __future__ import annotations

from core.intent.engine import IntentResult
from core.security import RiskLevel, classify_risk, requires_approval
import config


class DecisionEngine:
    def decide(self, text: str, intent: IntentResult) -> dict:
        primary = intent.primary
        size = "small" if len(text) < 80 else ("medium" if len(text) < 240 else "large")
        risk = classify_risk(primary, text)
        model_role = "chat"
        if primary in {"CODING", "DEBUG", "PROJECT_TASK"}:
            model_role = "coding"
        elif primary == "RESEARCH":
            model_role = "research"
        elif primary == "MEDIA_TASK":
            model_role = "vision"
        elif primary in {"QUESTION", "CHAT"}:
            model_role = "fast"
        tools = []
        if primary in {"CODING", "PROJECT_TASK", "DEBUG"}:
            tools = ["filesystem", "python", "terminal", "tester", "debugger"]
        elif primary == "FILE_OPERATION":
            tools = ["filesystem"]
        elif primary == "RESEARCH":
            tools = ["web"]
        elif primary == "BROWSER_TASK":
            tools = ["browser"]
        elif primary == "SYSTEM_OPERATION":
            tools = ["env"]
        parallel = size != "small" and primary in {"CODING", "PROJECT_TASK", "RESEARCH"}
        approve = requires_approval(risk, config.SAFE_MODE)
        return {
            "size": size,
            "risk": risk.value if isinstance(risk, RiskLevel) else str(risk),
            "model_role": model_role,
            "tools": tools,
            "parallel": parallel,
            "needs_approval": approve,
        }

from __future__ import annotations

import os
import platform
import shutil
import subprocess
from typing import Any

import config
from core.llm_client import OllamaClient


def _run(cmd: list[str]) -> dict[str, Any]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=12, encoding="utf-8", errors="replace")
        out = (r.stdout or r.stderr or "").strip().splitlines()
        return {"ok": r.returncode == 0, "version": out[0] if out else "", "detail": (r.stderr or "")[:200]}
    except Exception as e:
        return {"ok": False, "version": "", "detail": str(e)}


def environment_report(llm: OllamaClient | None = None) -> dict[str, Any]:
    llm = llm or OllamaClient()
    health = llm.health_check()
    ram = {}
    try:
        import psutil  # type: ignore
        ram = {"total_gb": round(psutil.virtual_memory().total / (1024 ** 3), 2), "percent": psutil.virtual_memory().percent}
    except Exception:
        ram = {"total_gb": None, "percent": None}

    disk = shutil.disk_usage(str(config.BASE_DIR))
    tools = {
        "windows": {"ok": os.name == "nt", "version": platform.platform()},
        "python": _run(["python", "--version"]),
        "git": _run(["git", "--version"]),
        "node": _run(["node", "--version"]),
        "npm": _run(["npm", "--version"]),
        "powershell": {"ok": True, "version": "Windows PowerShell"},
        "ffmpeg": _run(["ffmpeg", "-version"]),
        "docker": _run(["docker", "--version"]),
        "ollama": {"ok": bool(health.get("ok")), "version": ", ".join(health.get("models", [])[:6]), "detail": health.get("error", "")},
    }
    missing = [name for name, info in tools.items() if not info.get("ok") and name not in {"ffmpeg", "docker"}]
    optional_missing = [name for name in ("ffmpeg", "docker") if not tools[name].get("ok")]
    return {
        "ok": tools["python"]["ok"] and tools["ollama"]["ok"],
        "tools": tools,
        "missing": missing,
        "optional_missing": optional_missing,
        "disk_free_gb": round(disk.free / (1024 ** 3), 2),
        "ram": ram,
        "internet": _internet(),
        "gpu": _gpu(),
    }


def _internet() -> bool:
    try:
        import urllib.request
        urllib.request.urlopen("https://example.com", timeout=3)
        return True
    except Exception:
        return False


def _gpu() -> str:
    try:
        r = subprocess.run(
            ["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip().splitlines()[0]
    except Exception:
        pass
    return "algılanamadı"


def format_env_report(report: dict[str, Any]) -> str:
    lines = ["Ortam kontrolü:"]
    for name, info in report["tools"].items():
        mark = "OK" if info.get("ok") else "YOK"
        extra = info.get("version") or info.get("detail") or ""
        lines.append(f"  [{mark}] {name}: {extra}")
    if report["missing"]:
        lines.append("Eksik zorunlu araçlar: " + ", ".join(report["missing"]))
    if report["optional_missing"]:
        lines.append("Opsiyonel eksikler: " + ", ".join(report["optional_missing"]))
    lines.append(f"Disk boş: {report['disk_free_gb']} GB")
    lines.append(f"İnternet: {'var' if report['internet'] else 'yok / kısıtlı'}")
    lines.append(f"GPU: {report['gpu']}")
    return "\n".join(lines)

import sys
import json
import time
import requests
import config


class OllamaClient:
    """
    Dual-model Ollama istemcisi:
      - self.model       → genel (kod/plan) → config.OLLAMA_CODE_MODEL
      - self.chat_model  → sohbet (hızlı)   → config.OLLAMA_CHAT_MODEL
    """

    def __init__(
        self,
        base_url: str = None,
        model: str = None,
        chat_model: str = None,
        timeout: int = None,
        temperature: float = None,
        ctx_window: int = None,
    ):
        self.base_url = base_url or config.OLLAMA_BASE_URL
        self.model = model or config.OLLAMA_CODE_MODEL      # Kod/Plan modeli
        self.chat_model = chat_model or config.OLLAMA_CHAT_MODEL  # Sohbet modeli
        self.timeout = timeout or config.OLLAMA_TIMEOUT
        self.temperature = temperature if temperature is not None else config.OLLAMA_TEMPERATURE
        self.ctx_window = ctx_window or config.OLLAMA_CTX_WINDOW
        self.session = requests.Session()
        self.max_retries = getattr(config, "OLLAMA_MAX_RETRIES", 2)

    # ─── Sağlık / model kontrolü ────────────────────────────────────────────

    def health_check(self) -> dict:
        try:
            r = self.session.get(f"{self.base_url}/api/tags", timeout=10)
            if r.status_code == 200:
                data = r.json()
                models = [m["name"] for m in data.get("models", [])]
                return {"ok": True, "models": models, "base_url": self.base_url}
            return {"ok": False, "error": f"HTTP {r.status_code}"}
        except requests.RequestException as e:
            return {"ok": False, "error": f"Baglanti hatasi: {e}"}

    def model_available(self, model_name: str = None) -> bool:
        return self.resolve_name(model_name or self.model, allow_vision=True) is not None

    def resolve_name(self, wanted: str, allow_vision: bool = False) -> str | None:
        h = self.health_check()
        if not h.get("ok"):
            return None
        models = h.get("models", []) or []
        w = (wanted or "").lower().strip()
        if not w:
            return None
        base = w.split(":")[0]
        exact = []
        family = []
        for m in models:
            ml = m.lower()
            if (not allow_vision) and "vision" in ml:
                continue
            mbase = ml.split(":")[0]
            if ml == w or ml == f"{base}:latest":
                exact.append(m)
            elif mbase == base:
                family.append(m)
        if exact:
            return exact[0]
        if family:
            return family[0]
        return None

    def bind_installed_models(self) -> None:
        chat = self.resolve_name(self.chat_model, allow_vision=False) or self.resolve_name("llama3.2", allow_vision=False)
        code = self.resolve_name(self.model, allow_vision=False) or self.resolve_name("qwen2.5-coder", allow_vision=False)
        if chat:
            self.chat_model = chat
        if code:
            self.model = code

    # ─── İlerleme göstergesi (spinner) ──────────────────────────────────────

    def _run_with_spinner(self, func, label="Model yanıt üretiyor"):
        import threading
        stop_event = threading.Event()
        start = time.time()

        print(f"  \033[33m>> {label}...\033[0m", end="", flush=True)

        def progress_dots():
            while not stop_event.is_set():
                time.sleep(2.0)
                if not stop_event.is_set():
                    sys.stdout.write(".")
                    sys.stdout.flush()

        t = threading.Thread(target=progress_dots, daemon=True)
        t.start()
        try:
            res = func()
            elapsed = int(time.time() - start)
            print(f" \033[32m[{elapsed}sn]\033[0m", flush=True)
            return res
        except Exception:
            elapsed = int(time.time() - start)
            print(f" \033[31m[Hata - {elapsed}sn]\033[0m", flush=True)
            raise
        finally:
            stop_event.set()
            t.join(timeout=0.5)

    # ─── generate() — kod/plan için (qwen2.5-coder) ─────────────────────────

    def generate(
        self,
        prompt: str,
        system: str = None,
        temperature: float = None,
        max_tokens: int = None,
        label: str = "Model yanıt üretiyor",
        use_code_model: bool = True,   # Varsayılan: kod modeli kullan
    ) -> str:
        model_to_use = self.model if use_code_model else self.chat_model
        payload = {
            "model": model_to_use,
            "prompt": prompt,
            "stream": False,
            "options": {
                "temperature": temperature if temperature is not None else self.temperature,
                "num_ctx": self.ctx_window,
            },
        }
        if system:
            payload["system"] = system
        if max_tokens:
            payload["options"]["num_predict"] = max_tokens

        def _do_post():
            last_err = None
            for attempt in range(self.max_retries + 1):
                try:
                    r = self.session.post(
                        f"{self.base_url}/api/generate",
                        json=payload,
                        timeout=self.timeout,
                    )
                    r.raise_for_status()
                    data = r.json()
                    return data.get("response", "")
                except requests.RequestException as e:
                    last_err = e
                    time.sleep(min(2 ** attempt, 4))
            raise last_err

        try:
            return self._run_with_spinner(_do_post, label)
        except requests.RequestException as e:
            fallback = self._fallback_model(model_to_use)
            if fallback and fallback != model_to_use:
                payload["model"] = fallback
                try:
                    return self._run_with_spinner(_do_post, f"{label} (fallback)")
                except Exception:
                    pass
            return f"[LLM_HATA: {type(e).__name__}: {e}]"
        except Exception as e:
            return f"[LLM_HATA: {type(e).__name__}: {e}]"

    def _fallback_model(self, failed: str) -> str | None:
        failed_l = (failed or "").lower()
        order = [
            getattr(config, "OLLAMA_CHAT_MODEL", "llama3.2"),
            getattr(config, "OLLAMA_FAST_MODEL", "llama3.2"),
            "llama3.2:latest",
            "llama3.2",
            self.chat_model,
            self.model,
        ]
        for m in order:
            if not m:
                continue
            if m.lower() == failed_l:
                continue
            if "vision" in m.lower():
                continue
            return m
        return None

    # ─── chat() — senkron (yavaş, nadiren kullanılır) ───────────────────────

    def chat(self, messages: list[dict], temperature: float = None, max_tokens: int = None, use_code_model: bool = False) -> str:
        model_to_use = self.model if use_code_model else self.chat_model
        payload = {
            "model": model_to_use,
            "messages": messages,
            "stream": False,
            "think": False,
            "options": {
                "temperature": temperature if temperature is not None else self.temperature,
                "num_ctx": self.ctx_window,
            },
        }
        if max_tokens:
            payload["options"]["num_predict"] = max_tokens
        try:
            r = self.session.post(
                f"{self.base_url}/api/chat",
                json=payload,
                timeout=self.timeout,
            )
            r.raise_for_status()
            data = r.json()
            msg = data.get("message", {})
            return msg.get("content", "")
        except requests.RequestException as e:
            return f"[LLM_HATA: {type(e).__name__}: {e}]"
        except Exception as e:
            return f"[LLM_HATA: {type(e).__name__}: {e}]"

    # ─── chat_stream() — sohbet (think kapalı, Türkçe temizleme) ────────────

    def chat_stream(
        self,
        messages: list[dict],
        temperature: float = None,
        max_tokens: int = None,
        on_token=None,
        use_code_model: bool = False,
        think: bool = False,
    ) -> str:
        from core.turkish import StreamThinkFilter, polish_turkish

        model_to_use = self.model if use_code_model else self.chat_model
        payload = {
            "model": model_to_use,
            "messages": messages,
            "stream": True,
            "think": bool(think),
            "options": {
                "temperature": temperature if temperature is not None else 0.35,
                "num_ctx": self.ctx_window,
            },
        }
        if max_tokens:
            payload["options"]["num_predict"] = max_tokens

        filt = StreamThinkFilter()
        full_chunks: list[str] = []

        def emit(raw: str) -> None:
            visible = filt.feed(raw)
            if not visible:
                return
            full_chunks.append(visible)
            if on_token:
                on_token(visible)
            else:
                sys.stdout.write(visible)
                sys.stdout.flush()

        def consume(resp) -> None:
            for line in resp.iter_lines():
                if not line:
                    continue
                try:
                    chunk = json.loads(line)
                except Exception:
                    continue
                token = (chunk.get("message", {}) or {}).get("content", "") or ""
                if token:
                    emit(token)
                if chunk.get("done", False):
                    break

        try:
            r = self.session.post(
                f"{self.base_url}/api/chat",
                json=payload,
                stream=True,
                timeout=self.timeout,
            )
