class VisionTool:
    def __init__(self, llm: OllamaClient | None = None):
        self.llm = llm or OllamaClient()
        self.router = ModelRouter(self.llm)

    def analyze_image(self, path: str, prompt: str = "Bu görseli Türkçe kısaca açıkla.") -> dict:
        info = self.router.resolve("VISION")
        model = info.get("model")
        if not model:
            return {"success": False, "error": "Vision modeli yok. Mevcut modellerle devam."}
        p = Path(path)
        if not p.exists():
            return {"success": False, "error": "Görsel bulunamadı"}
        b64 = base64.b64encode(p.read_bytes()).decode("ascii")
        try:
            r = self.llm.session.post(
                f"{self.llm.base_url}/api/generate",
                json={
                    "model": model,
                    "prompt": prompt,
                    "images": [b64],
                    "stream": False,
                    "options": {"temperature": 0.2, "num_predict": 250},
                },
                timeout=min(self.llm.timeout, 120),
            )
            r.raise_for_status()
            return {"success": True, "model": model, "text": r.json().get("response", "")}
        except Exception as e:
            return {"success": False, "error": str(e), "model": model}

    def ocr_stub(self, path: str) -> dict:
        r = self.analyze_image(path, "Görseldeki tüm metni olduğu gibi çıkar. Sadece metin yaz.")
        return r

import re
import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse, urljoin
import config


class WebTool:
    SAFE_DOMAINS = [
        "python.org",
        "docs.python.org",
        "pypi.org",
        "pip.pypa.io",
        "stackoverflow.com",
        "docs.djangoproject.com",
        "flask.palletsprojects.com",
        "fastapi.tiangolo.com",
        "pydantic.dev",
        "requests.readthedocs.io",
        "github.com",
        "docs.github.com",
        "developer.mozilla.org",
        "w3schools.com",
        "devdocs.io",
        "learn.microsoft.com",
        "nodejs.org",
        "docs.npmjs.com",
    ]
    allowed_domains = SAFE_DOMAINS

    def __init__(self, timeout: int = 30):
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers.update({
            "User-Agent": "REIS-AI-Agent/1.0 (Research Tool)"
        })

    def _is_safe_domain(self, url: str) -> tuple[bool, str]:
        try:
            parsed = urlparse(url)
            if parsed.scheme not in ("http", "https"):
                return False, f"Gecersiz protokol: {parsed.scheme}"
            host = parsed.hostname or ""
            if not host:
                return False, "Host tanimlanamadi"
            for safe in self.SAFE_DOMAINS:
                if host == safe or host.endswith("." + safe):
                    return True, "OK"
            return False, f"Domain beyaz listede degil: {host}. Sadece resmi dokumantasyon siteleri arastirilabilir."
        except Exception as e:
            return False, f"URL parse hatasi: {e}"

    def fetch(self, url: str) -> dict:
        safe, reason = self._is_safe_domain(url)
        if not safe:
            return {"success": False, "error": reason, "url": url}
        try:
            r = self.session.get(url, timeout=self.timeout, allow_redirects=True)
            r.raise_for_status()
            content_type = r.headers.get("Content-Type", "")
            text = ""
            if "text" in content_type or "json" in content_type or "xml" in content_type:
                text = r.text
            return {
                "success": True,
                "url": url,
                "final_url": r.url,
                "status": r.status_code,
                "content_type": content_type,
                "content": text,
                "length": len(r.content),
            }
        except Exception as e:
            return {"success": False, "error": f"{type(e).__name__}: {e}", "url": url}

    def fetch_readable(self, url: str, max_chars: int = 8000) -> dict:
        r = self.fetch(url)
        if not r["success"]:
            return r
        content = r.get("content", "")
        if not content:
            return {"success": False, "error": "Icerik bos", "url": url}
        try:
            soup = BeautifulSoup(content, "lxml")
        except Exception:
            soup = BeautifulSoup(content, "html.parser")
        for tag in soup(["script", "style", "nav", "footer", "header", "aside"]):
            tag.decompose()
        text = soup.get_text(separator="\n", strip=True)
        text = re.sub(r"\n{3,}", "\n\n", text)
        if len(text) > max_chars:
            text = text[:max_chars] + "\n\n... [truncated]"
        r["readable_text"] = text
        return r

    def search_web(self, query: str) -> dict:
